# Build plt stub -> symbol map from objdump of the plt section only
import subprocess, re
out = subprocess.run(["objdump","-d","-M","intel","--section=.plt.sec","/workspace/artifacts/target/busybox"],capture_output=True,text=True).stdout
cur=None; m={}
for line in out.splitlines():
    h = re.match(r'^0*([0-9a-f]+) <([^>]+)>:', line)
    if h:
        cur = h.group(2).replace('@plt',''); m[h.group(1)] = cur
for addr,name in sorted(m.items(), key=lambda kv: int(kv[0],16)):
    print(addr, name)
